-- Migration 191: song data fill from the 2026-11-05 clean-up run. Every value
-- here came from two agreeing sources (GPT-5.5 + MusicBrainz, LRCLIB or Spotify)
-- or, where only one source had it, was checked by hand; anything unconfirmed
-- was left out. Writes only touch songs that still exist and fields that are
-- still empty — except recording years where both sources agree the stored
-- year is a reissue date, and the re-tagging onto the approved vocabularies.

create or replace function pg_temp.person(n text) returns uuid language plpgsql as $$
declare i uuid;
begin
  select id into i from public.people where lower(name) = lower(n) limit 1;
  if i is null then insert into public.people (name) values (n) returning id into i; end if;
  return i;
end $$;

create or replace function pg_temp.language(n text) returns uuid language plpgsql as $$
declare i uuid;
begin
  select id into i from public.languages where lower(name) = lower(n) limit 1;
  if i is null then insert into public.languages (name) values (n) returning id into i; end if;
  return i;
end $$;

create or replace function pg_temp.merge_artist(from_name text, to_name text) returns void language plpgsql as $$
declare f uuid; t uuid;
begin
  select id into f from public.artists where name = from_name;
  if f is null then return; end if;
  select id into t from public.artists where name = to_name;
  if t is null then update public.artists set name = to_name where id = f; return; end if;
  update public.song_recording_artists set artist_id = t
  where artist_id = f and song_id not in (select song_id from public.song_recording_artists where artist_id = t);
  delete from public.artists where id = f;
end $$;

