insert into public.song_composers (song_id, person_id)
select distinct w.song_id, pg_temp.person(w.name) from w join public.songs s on s.id = w.song_id
where w.kind = 'c' and not exists (select 1 from public.song_composers c where c.song_id = w.song_id)
  and not exists (select 1 from public.song_lyricists l where l.song_id = w.song_id);
insert into public.song_lyricists (song_id, person_id)
select distinct w.song_id, pg_temp.person(w.name) from w join public.songs s on s.id = w.song_id
where w.kind = 'l' and not exists (select 1 from public.song_lyricists l where l.song_id = w.song_id);

-- 3. Tonality, meter, vibe, year written, first line, hook — only where empty
update public.songs s set
  tonality = coalesce(s.tonality, v.tonality),
  meter = coalesce(s.meter, v.meter),
  vibe = coalesce(s.vibe, v.vibe),
  year_written = coalesce(s.year_written, case when v.year_written <= coalesce((select min(r.year) from public.song_recording_artists r where r.song_id = s.id), 9999) then v.year_written end),
  first_line = coalesce(s.first_line, v.first_line),
  hook = coalesce(s.hook, v.hook),
  updated_at = now()
