delete from public.song_genres sg using (select distinct song_id from g where replace) r where sg.song_id = r.song_id;
insert into public.song_genres (song_id, genre_id)
select g.song_id, x.id from g join public.genres x on x.name = g.name join public.songs s on s.id = g.song_id
where g.replace or not exists (select 1 from public.song_genres e where e.song_id = g.song_id)
on conflict do nothing;
delete from public.song_themes st using (select distinct song_id from t where replace) r where st.song_id = r.song_id;
insert into public.song_themes (song_id, theme_id)
select t.song_id, x.id from t join public.themes x on x.name = t.name join public.songs s on s.id = t.song_id
where t.replace or not exists (select 1 from public.song_themes e where e.song_id = t.song_id)
on conflict do nothing;

